import{_ as o,o as a,c as l,a2 as t}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"ダウンロードマネージャー","description":"原寸画像ダウンロード、一括保存、キュー管理、オフラインライブラリ","frontmatter":{"title":"ダウンロードマネージャー","description":"原寸画像ダウンロード、一括保存、キュー管理、オフラインライブラリ"},"headers":[],"relativePath":"features/downloads.md","filePath":"features/downloads.md","lastUpdated":1786166106000}'),r={name:"features/downloads.md"};function i(n,e,d,s,c,u){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="ダウンロードマネージャー" tabindex="-1">ダウンロードマネージャー <a class="header-anchor" href="#ダウンロードマネージャー" aria-label="Permalink to &quot;ダウンロードマネージャー&quot;">​</a></h1><p>作品の画像保存およびオフライン保存用キュー管理機能の仕様です。</p><hr><h2 id="保存オプション-appsettings" tabindex="-1">保存オプション (<code>AppSettings</code>) <a class="header-anchor" href="#保存オプション-appsettings" aria-label="Permalink to &quot;保存オプション (`AppSettings`)&quot;">​</a></h2><ul><li><strong>原寸画像保存</strong>: メタデータからオリジナルの画像 URL を取得して保存。</li><li><strong>マルチページ一括保存</strong>: マンガ等の全ページをフォルダにまとめてダウンロード。</li><li><strong>フォルダ自動振り分け</strong>: <ul><li><code>downloadFolderByArtist</code>: 作者名（ユーザーID）ごとにフォルダを作成して分類。</li><li><code>downloadFolderByWork</code>: 作品ID（タイトル）ごとにサブフォルダを作成。</li></ul></li></ul><hr><h2 id="キュー管理-downloadqueuescreen" tabindex="-1">キュー管理 (<code>DownloadQueueScreen</code>) <a class="header-anchor" href="#キュー管理-downloadqueuescreen" aria-label="Permalink to &quot;キュー管理 (`DownloadQueueScreen`)&quot;">​</a></h2><ul><li><strong>並列タスク数制御 (<code>simultaneousDownloads</code>)</strong>: 同時ダウンロード数を 1〜5 の範囲で設定可能。</li><li><strong>状態管理</strong>: キュー内の各タスク（待機中、ダウンロード中、完了、エラー、一時停止）の進行状況とプログレス表示。</li><li><strong>ネットワーク制御 (<code>offlineWifiOnly</code>)</strong>: Wi-Fi 接続時のみダウンロードを実行する制限設定。</li></ul><hr><h2 id="オフラインライブラリ-offlinelibraryscreen" tabindex="-1">オフラインライブラリ (<code>OfflineLibraryScreen</code>) <a class="header-anchor" href="#オフラインライブラリ-offlinelibraryscreen" aria-label="Permalink to &quot;オフラインライブラリ (`OfflineLibraryScreen`)&quot;">​</a></h2><p>保存された作品データは Room データベースで管理されます。</p><ul><li><strong>テーブル構造</strong>: <ul><li><code>SavedIllustEntity</code>: 保存済み作品の基本情報（ID、タイトル、作者、保存日時）</li><li><code>SavedIllustPageEntity</code>: 各ページのローカルファイルパスおよび画像インデックス</li></ul></li><li>ネットワーク非接続時でも、保存済み作品をライブラリからオフライン閲覧可能です。</li></ul>',12)])])}const p=o(r,[["render",i]]);export{h as __pageData,p as default};
